parts.text:
{
  "references": [
    {
      "id": "R1",
      "summary_ko": "착지 동작이 비현실적으로 보임."
    },
    {
      "id": "R2",
      "summary_ko": "신체가 회전하며 부자연스러운 자세가 됨."
    },
    {
      "id": "R3",
      "summary_ko": "다리 사이에 평균대를 두고 착지함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "밝기 및 구조 변화 후 복귀하는 깜빡임 또는 순간 변형 패턴."
    },
    {
      "id": "C2",
      "summary_ko": "착지 시 체조 선수의 다리가 평균대 구조를 비현실적으로 관통하며 걸침."
    },
    {
      "id": "C3",
      "summary_ko": "착지 후 체조 선수의 머리카락이 중력을 거스르고 불꽃처럼 위로 뜨는 부자연스러운 움직임."
    },
    {
      "id": "C4",
      "summary_ko": "평균대 위 공중제비 및 착지 중 신체 분절이 비물리적으로 왜곡되고 흐려짐."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 구체적 대상이 없는 일반적 측정 가설로 착지의 비현실성과 관련 여부가 불명확합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "uncertain",
      "reason_ko": "R1의 모호한 비현실적 착지 설명이 C2의 평균대 관통 착지 현상을 지칭하는 것인지 판단하기 충분하지 않습니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R1은 착지 자체의 이상을 언급하는 반면 C3는 착지 후 머리카락의 움직임 이상을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "uncertain",
      "reason_ko": "C4의 신체 왜곡이 착지의 비현실성 원인일 수 있으나 R1의 설명이 너무 포괄적이어서 동일 사건인지 불확실합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 식별된 대상이 없는 측정치 변화 가설로 R2의 신체 회전 이상과 동일한지 판단할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "R2는 공중제비 중 신체 자세의 이상에 대한 것이고, C2는 착지 시 다리가 평균대를 관통하는 결함입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R2는 신체 자세 이상이고 C3는 머리카락의 이상 현상으로 대상과 현상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "same",
      "reason_ko": "두 설명 모두 공중제비 및 전환 과정에서 신체가 비정상적/비물리적인 자세와 왜곡을 보이는 현상을 공유합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "C1은 대상이 특정되지 않은 측정 제안으로 R3와의 일치 여부를 확인할 수 없습니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "verdict": "same",
      "reason_ko": "체조 선수가 다리 사이에 평균대를 걸치며 착지하는(straddle) 동일한 비정상 착지 현상을 설명합니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "R3는 다리와 평균대 간의 착지 문제인 반면 C3는 머리카락의 움직임 결함입니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "R3는 다리 사이에 평균대가 끼는 착지 상황이며 C4는 공중제비 및 착지 중 신체 분절의 왜곡/흐림 현상입니다."
    }
  ]
}
